import{_ as a,c as r,o,ag as t}from"./chunks/framework.C86mscM5.js";const l="/fe-handbook/assets/image-20240713150457449.42nkVuDk.png",n="/fe-handbook/assets/image-20240713150650468.CMKxNErY.png",u=JSON.parse('{"title":"性能优化","description":"","frontmatter":{},"headers":[],"relativePath":"advance/performance/index.md","filePath":"advance/performance/index.md","lastUpdated":1788689791000}'),d={name:"advance/performance/index.md"};function i(h,e,s,c,p,b){return o(),r("div",null,e[0]||(e[0]=[t('<h1 id="性能优化" tabindex="-1">性能优化 <a class="header-anchor" href="#性能优化" aria-label="Permalink to &quot;性能优化&quot;">​</a></h1><p>页面性能优化应先定位瓶颈，再选择措施，并在相同设备、网络和操作流程下比较优化前后的结果。本页整理常见的加载与产物优化方法，以及原有项目笔记中的适用条件。</p><h2 id="检测工具与指标" tabindex="-1">检测工具与指标 <a class="header-anchor" href="#检测工具与指标" aria-label="Permalink to &quot;检测工具与指标&quot;">​</a></h2><ul><li><a href="https://developer.chrome.com/docs/lighthouse/overview/" target="_blank" rel="nofollow noopener noreferrer">Lighthouse</a>：通过实验室测试发现加载、资源体积等问题，适合建立基线和检查改动。</li><li><a href="https://pagespeed.web.dev/" target="_blank" rel="nofollow noopener noreferrer">PageSpeed Insights</a>：结合实验室诊断与可用的真实用户数据；访问量不足时可能没有真实用户报告。</li><li>Chrome DevTools：用 Network 查看请求与缓存，用 Performance 定位主线程耗时，用 Coverage 辅助查找未使用的代码。覆盖率取决于实际执行过的页面和操作，不能据此直接删除代码。</li></ul><table tabindex="0"><thead><tr><th>指标</th><th>关注的问题</th><th>良好值</th></tr></thead><tbody><tr><td>LCP（最大内容绘制）</td><td>主要内容多久可见</td><td>≤ 2.5 秒</td></tr><tr><td>INP（交互到下一次绘制）</td><td>点击、输入等交互是否及时响应</td><td>≤ 200 毫秒</td></tr><tr><td>CLS（累积布局偏移）</td><td>内容是否意外移动</td><td>≤ 0.1</td></tr></tbody></table><p>以上是 <a href="https://web.dev/articles/vitals" target="_blank" rel="nofollow noopener noreferrer">Core Web Vitals</a> 的良好阈值，真实用户评估以访问样本的第 75 百分位为准。单次 Lighthouse 得分不能替代真实用户体验；加载测试中的 TBT 也不等同于覆盖实际交互的 INP。</p><p>先记录首屏资源体积、关键请求和主要交互耗时，每次针对一个已确认的瓶颈验证收益，避免只追求请求数量或跑分。</p><h2 id="代码分割" tabindex="-1">代码分割 <a class="header-anchor" href="#代码分割" aria-label="Permalink to &quot;代码分割&quot;">​</a></h2><p>将代码按路由或功能拆分，让首屏只加载当前需要的部分。例如编辑器、图表、导出功能可以在使用时通过动态 <code>import()</code> 加载。构建工具需要支持并启用对应的分包能力。</p><p>分包也可以提取共享依赖，减少重复代码。按需加载与提取公共包的目的不同：文件拆开后若仍全部在首屏请求，未必能减少首屏工作量。</p><p>不要机械地把每个模块拆成小文件，也不要把所有依赖合成一个大包。需要结合请求开销、缓存复用、压缩效果和执行耗时确定边界；延后加载的功能还应有加载反馈和失败重试入口。参见 <a href="https://web.dev/learn/performance/code-split-javascript" target="_blank" rel="nofollow noopener noreferrer">web.dev：代码分割</a>。</p><p>框架示例见 <a href="/fe-handbook/framework/react/Code-Splitting.html">React 代码分割</a>，构建工具配置见 <a href="/fe-handbook/build-tools/bundler/webpack/">Webpack</a> 和 <a href="/fe-handbook/build-tools/bundler/vite/">Vite</a>。</p><h2 id="静态资源内联" tabindex="-1">静态资源内联 <a class="header-anchor" href="#静态资源内联" aria-label="Permalink to &quot;静态资源内联&quot;">​</a></h2><p>内联少量关键 CSS 或很小的静态资源，可以省去额外请求，让首屏所需内容更早到达。图片转 data URL 的基础用法见 <a href="/fe-handbook/other/matrix/image-to-base64.html">图片转 base64</a>。</p><p>内联会增加 HTML 或引用文件体积，资源不能再单独缓存，跨页面使用时也可能重复传输；base64 编码本身还会增大原始数据。因此应只在实际测量有收益时使用，并检查站点 CSP 是否允许相应内联方式。</p><p>“减少 HTTP 请求”是手段，不是独立的优化目标。尤其在 HTTP/2、HTTP/3 场景下，应同时考虑关键资源是否被延迟、缓存是否失效和传输总量，不能仅根据请求数决定是否内联或合并。参见 <a href="https://web.dev/learn/performance/optimize-resource-loading" target="_blank" rel="nofollow noopener noreferrer">web.dev：优化资源加载</a>。</p><h2 id="产物体积优化" tabindex="-1">产物体积优化 <a class="header-anchor" href="#产物体积优化" aria-label="Permalink to &quot;产物体积优化&quot;">​</a></h2><h3 id="减少重复依赖" tabindex="-1">减少重复依赖 <a class="header-anchor" href="#减少重复依赖" aria-label="Permalink to &quot;减少重复依赖&quot;">​</a></h3><p>先检查依赖树和构建产物分析报告，定位同一库的多个版本、重复打包的工具函数或重复引入的 polyfill。对于兼容的版本，可以统一依赖范围、使用包管理器的去重能力，或调整公共模块提取方式。</p><p>依赖树中出现多个版本不一定意味着浏览器下载了多份代码，应以实际产物为准。不要为了去重强行覆盖不兼容的大版本；调整后需要验证依赖行为。</p><h3 id="使用更轻量的库" tabindex="-1">使用更轻量的库 <a class="header-anchor" href="#使用更轻量的库" aria-label="Permalink to &quot;使用更轻量的库&quot;">​</a></h3><p>只使用少量功能时，优先评估原生能力、库提供的按需入口，以及能被 tree shaking 消除未使用代码的模块形式。确实需要替换库时，比较最终产物及功能覆盖，而不是只看安装包大小。</p><p>日期、国际化、精度处理等库的替换可能改变行为。应保留业务必需能力，验证兼容性，并确认按需引入确实减少了产物；不要默认“换成具名导入”一定有效。</p><h3 id="调整-browserslist-目标范围" tabindex="-1">调整 Browserslist 目标范围 <a class="header-anchor" href="#调整-browserslist-目标范围" aria-label="Permalink to &quot;调整 Browserslist 目标范围&quot;">​</a></h3><p>附件中的“提升 Browserslist 范围”更准确地说是：在业务允许时提高最低支持版本、缩小旧浏览器兼容范围，使使用这些目标的工具减少不必要的语法转换、前缀或 polyfill。</p><p>先依据用户浏览器分布和产品支持约定确定目标，再修改配置；这会影响旧设备的可用性，不能只为缩小包体而调整。不同工具读取目标的方式不同，需检查构建链是否实际使用 Browserslist。配置说明见 <a href="/fe-handbook/build-tools/compiler/babel/browserslist.html">Browserslist</a> 和 <a href="https://github.com/browserslist/browserslist" target="_blank" rel="nofollow noopener noreferrer">官方项目文档</a>。</p><h3 id="按需引入-polyfill" tabindex="-1">按需引入 polyfill <a class="header-anchor" href="#按需引入-polyfill" aria-label="Permalink to &quot;按需引入 polyfill&quot;">​</a></h3><p>语法转换不等于运行时 API 补齐。使用 Babel 的项目可根据目标环境和代码用法，配置 <code>@babel/preset-env</code> 的 <code>useBuiltIns: &#39;usage&#39;</code> 与匹配的 <code>core-js</code> 版本，减少不需要的 ECMAScript polyfill。</p><p>避免同时重复引入全量 polyfill。还需检查未经过 Babel 处理的依赖以及 Web API：<code>core-js</code> 不能补齐所有浏览器能力，例如 <code>fetch</code> 需要单独评估。参见 <a href="https://babeljs.io/docs/babel-preset-env/" target="_blank" rel="nofollow noopener noreferrer">Babel preset-env 文档</a>。</p><h3 id="图片压缩" tabindex="-1">图片压缩 <a class="header-anchor" href="#图片压缩" aria-label="Permalink to &quot;图片压缩&quot;">​</a></h3><p>按实际展示尺寸输出图片，根据画质需求选择压缩质量，并在兼容性允许时使用 WebP、AVIF 等格式。使用 <code>srcset</code>、<code>sizes</code> 为不同设备提供合适尺寸，避免小区域下载大图。</p><p>对首屏外图片按需懒加载，但不要将首屏关键图片，尤其是 LCP 图片，机械地设为懒加载。声明图片宽高或宽高比以预留空间，减少布局偏移。参见 <a href="https://web.dev/learn/performance/image-performance" target="_blank" rel="nofollow noopener noreferrer">web.dev：图片性能</a>。</p><h2 id="传输与缓存" tabindex="-1">传输与缓存 <a class="header-anchor" href="#传输与缓存" aria-label="Permalink to &quot;传输与缓存&quot;">​</a></h2><h3 id="文件合并与-cdn" tabindex="-1">文件合并与 CDN <a class="header-anchor" href="#文件合并与-cdn" aria-label="Permalink to &quot;文件合并与 CDN&quot;">​</a></h3><p>旧笔记中的“将 vue.runtime.js、vue-router.js、vuex.js 合成一个文件”是减少请求的一种历史做法。合并可能减少请求开销，但也可能增加首屏下载量，并让其中一个依赖更新时整个文件的缓存失效，应结合前面的代码分割策略判断。</p><p>CDN 可以让静态资源从更靠近用户的节点分发，但缓存收益取决于资源 URL、响应头和命中情况；使用 CDN 并不自动意味着用户浏览器已有缓存。</p><h3 id="传输压缩" tabindex="-1">传输压缩 <a class="header-anchor" href="#传输压缩" aria-label="Permalink to &quot;传输压缩&quot;">​</a></h3><p>在服务端或 CDN 为 HTML、JavaScript、CSS 等文本资源配置 gzip 或 Brotli，根据请求的 <code>Accept-Encoding</code> 协商，并通过响应的 <code>Content-Encoding</code> 标明编码；按编码协商缓存时还需正确设置 <code>Vary: Accept-Encoding</code>。</p><p>已经压缩的 JPEG、PNG、WebP 等图片通常不适合再次进行通用压缩，SVG 等文本资源则可以受益。图片内容压缩与 HTTP 传输压缩是不同层面的工作。参见 <a href="https://developer.mozilla.org/en-US/docs/Web/HTTP/Guides/Compression" target="_blank" rel="nofollow noopener noreferrer">MDN：HTTP 压缩</a>。</p><h3 id="html-与静态资源缓存" tabindex="-1">HTML 与静态资源缓存 <a class="header-anchor" href="#html-与静态资源缓存" aria-label="Permalink to &quot;HTML 与静态资源缓存&quot;">​</a></h3><p>对需要及时更新的 HTML，可使用 <code>Cache-Control: no-cache</code> 配合 ETag 或 Last-Modified，让浏览器复用前先向服务端验证；<code>no-cache</code> 并不是禁止存储。</p><p>内容变化时 URL 也变化的静态资源（例如带内容哈希的 JS、CSS），可设置较长的 <code>max-age</code> 和 <code>immutable</code>。发布时需确保 HTML 引用的文件可用，并适当保留旧版本资源供已打开的页面继续加载。个性化内容不能直接套用公共 CDN 缓存策略。</p><p>基础概念见 <a href="/fe-handbook/fundamentals/network/http/caching.html">HTTP 缓存</a>，策略说明见 <a href="https://developer.mozilla.org/en-US/docs/Web/HTTP/Guides/Caching" target="_blank" rel="nofollow noopener noreferrer">MDN：HTTP 缓存</a>。</p><h2 id="框架特定技巧" tabindex="-1">框架特定技巧 <a class="header-anchor" href="#框架特定技巧" aria-label="Permalink to &quot;框架特定技巧&quot;">​</a></h2><h3 id="vue-2-中的-object-freeze-历史案例" tabindex="-1">Vue 2 中的 Object.freeze（历史案例） <a class="header-anchor" href="#vue-2-中的-object-freeze-历史案例" aria-label="Permalink to &quot;Vue 2 中的 Object.freeze（历史案例）&quot;">​</a></h3><p>对于不需要响应式更新的大型只读数据，可在交给 Vue 2 观察前使用 <code>Object.freeze</code>，避免对冻结对象建立响应式跟踪。这依赖于数据确实无需修改，不能作为通用的 JavaScript 提速方式。参见 <a href="https://v2.vuejs.org/v2/guide/instance.html#Data-and-Methods" target="_blank" rel="nofollow noopener noreferrer">Vue 2：实例与响应式数据</a>。</p><p><code>Object.freeze</code> 是浅冻结，嵌套对象不会自动全部冻结；冻结后也不能再直接修改顶层属性或数组结构。不要对需要交互更新的数据套用这一方式，也不要假设对已经建立的响应式跟踪可以通过冻结来撤销。参见 <a href="https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/Object/freeze" target="_blank" rel="nofollow noopener noreferrer">MDN：Object.freeze</a>。</p><p>以下保留原笔记中的大表格与 SVG 动画演示截图。截图缺少完整的环境、实现和优化后对照结果，仅作为历史案例，不代表可复现的性能收益：</p><p><img src="'+l+'" alt="历史演示：大型表格渲染与 Object.freeze 优化开关"></p><p><img src="'+n+'" alt="历史演示：1000 个 SVG 圆点动画与 Object.freeze 优化开关"></p>',50)]))}const m=a(d,[["render",i]]);export{u as __pageData,m as default};
